const input = $json;

const execution =
  input.execution ?? {};

const workflow =
  input.workflow ?? {};

const error =
  execution.error ??
  input.error ??
  {};

const workflowName =
  workflow.name ??
  'UNKNOWN_WORKFLOW';

const workflowId =
  workflow.id != null
    ? String(workflow.id)
    : null;

const executionId =
  execution.id != null
    ? String(execution.id)
    : null;

const executionUrl =
  typeof execution.url === 'string'
    ? execution.url
    : null;

const nodeName =
  execution.lastNodeExecuted ??
  error.node?.name ??
  error.nodeName ??
  null;

const errorMessage =
  error.message ??
  execution.error?.message ??
  input.message ??
  'Unknown n8n workflow error';

const errorStack =
  error.stack ??
  execution.error?.stack ??
  null;

return {
  json: {
    workflowName,
    workflowId,
    executionId,
    executionUrl,
    nodeName,
    errorMessage,
    errorStack,

    errorPayload: {
      execution: {
        id: executionId,
        url: executionUrl,
        mode:
          execution.mode ?? null,

        retryOf:
          execution.retryOf ?? null,

        lastNodeExecuted:
          execution.lastNodeExecuted ?? null
      },

      workflow: {
        id: workflowId,
        name: workflowName
      },

      error: {
        message: errorMessage,
        stack: errorStack,

        name:
          error.name ?? null,

        description:
          error.description ?? null,

        cause:
          error.cause ?? null
      }
    }
  }
};

const data = { ...$json.output };

function clean(value) {
  if (value === undefined || value === null) return null;

  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  return value;
}

// Limpiar valores
for (const key of [
  'serviceType',
  'vehicleType',
  'brand',
  'model',
  'engine',
  'originalPower',
  'ecuReference',
  'description'
]) {
  data[key] = clean(data[key]);
}

data.year = data.year ?? null;
data.vehicleRunning = data.vehicleRunning ?? null;
data.modifications = data.modifications ?? null;

// Normalizar tipo de vehículo
if (data.vehicleType) {
  const value = data.vehicleType.toLowerCase();

  if (['moto', 'motocicleta', 'motorcycle', 'scooter'].includes(value)) {
    data.vehicleType = 'MOTORCYCLE';
  } else if (['coche', 'car', 'automóvil', 'automovil', 'turismo'].includes(value)) {
    data.vehicleType = 'CAR';
  } else if (['furgoneta', 'van', 'furgón', 'furgon'].includes(value)) {
    data.vehicleType = 'VAN';
  } else if (['camión', 'camion', 'truck'].includes(value)) {
    data.vehicleType = 'TRUCK';
  } else {
    data.vehicleType = 'OTHER';
  }
}

// Campos obligatorios comunes
const required = [
  'brand',
  'model',
  'year'
];

// Campos según el servicio
switch (data.serviceType) {
  case 'REPROGRAMMING':
    required.push(
      'engine',
      'modifications',
      'vehicleRunning'
    );
    break;

  case 'ECU_REPAIR':
    required.push(
      'ecuReference',
      'vehicleRunning'
    );
    break;

  case 'ECU_CLONING':
    required.push(
      'ecuReference'
    );
    break;

  case 'OTHER':
  default:
    break;
}

const missingFields = required.filter((field) => {
  const value = data[field];

  if (value === null || value === undefined || value === '') {
    return true;
  }

  return false;
});

return {
  json: {
    ...data,
    missingFields,
    readyForHandoff: missingFields.length === 0
  }
};

