const body = $json.body;

const output = [];

for (const entry of body?.entry ?? []) {
  for (const change of entry?.changes ?? []) {
    const value = change?.value;

    const contacts = value?.contacts ?? [];
    const messages = value?.messages ?? [];

    for (const message of messages) {
      const contact =
        contacts.find((c) => c.wa_id === message.from) ??
        contacts[0];

      const base = {
        isMessage: true,

        phone: message.from
          ? `+${message.from}`
          : null,

        name:
          contact?.profile?.name ??
          null,

        providerMessageId:
          message.id ??
          null,

        whatsapp: {
          phoneNumberId:
            value?.metadata?.phone_number_id ??
            null,

          displayPhoneNumber:
            value?.metadata?.display_phone_number ??
            null,

          timestamp:
            message.timestamp ??
            null
        }
      };

      // =========================
      // TEXT
      // =========================
      if (message.type === 'text') {
        output.push({
          json: {
            ...base,

            messageType: 'TEXT',

            text:
              message.text?.body ??
              null,

            media: null,

            unsupportedMessageType: false
          },

          pairedItem: {
            item: 0
          }
        });

        continue;
      }

      // =========================
      // AUDIO / VOICE NOTE
      // =========================
      if (message.type === 'audio') {
        output.push({
          json: {
            ...base,

            messageType: 'AUDIO',

            text: null,

            media: {
              id:
                message.audio?.id ??
                null,

              mimeType:
                message.audio?.mime_type ??
                null,

              sha256:
                message.audio?.sha256 ??
                null,

              filename: null,

              voice:
                message.audio?.voice ??
                false
            },

            unsupportedMessageType: false
          },

          pairedItem: {
            item: 0
          }
        });

        continue;
      }

      // =========================
      // IMAGE
      // =========================
      if (message.type === 'image') {
        output.push({
          json: {
            ...base,

            messageType: 'IMAGE',

            text:
              message.image?.caption ??
              null,

            media: {
              id:
                message.image?.id ??
                null,

              mimeType:
                message.image?.mime_type ??
                null,

              sha256:
                message.image?.sha256 ??
                null,

              filename: null,

              voice: false
            },

            unsupportedMessageType: false
          },

          pairedItem: {
            item: 0
          }
        });

        continue;
      }

      // =========================
      // DOCUMENT
      // =========================
      if (message.type === 'document') {
        output.push({
          json: {
            ...base,

            messageType: 'DOCUMENT',

            text:
              message.document?.caption ??
              null,

            media: {
              id:
                message.document?.id ??
                null,

              mimeType:
                message.document?.mime_type ??
                null,

              sha256:
                message.document?.sha256 ??
                null,

              filename:
                message.document?.filename ??
                null,

              voice: false
            },

            unsupportedMessageType: false
          },

          pairedItem: {
            item: 0
          }
        });

        continue;
      }

      // =========================
      // TIPO NO SOPORTADO
      // =========================
      output.push({
        json: {
          ...base,

          messageType:
            message.type?.toUpperCase() ??
            'OTHER',

          text: null,

          media: null,

          unsupportedMessageType: true
        },

        pairedItem: {
          item: 0
        }
      });
    }
  }
}

if (output.length === 0) {
  return [
    {
      json: {
        isMessage: false
      },

      pairedItem: {
        item: 0
      }
    }
  ];
}

return output;

const input = $json;

const phone =
  input.phone ?? null;

const name =
  input.name ?? null;

const providerMessageId =
  input.providerMessageId ?? null;

const messageType =
  input.messageType ?? 'TEXT';

const text =
  typeof input.text === 'string'
    ? input.text.trim()
    : null;

const hasOriginalText =
  Object.prototype.hasOwnProperty.call(
    input,
    'originalText'
  );

const originalText =
  hasOriginalText
    ? (
        typeof input.originalText === 'string'
          ? input.originalText.trim() || null
          : null
      )
    : null;

if (!phone) {
  throw new Error(
    'Inbound WhatsApp message does not contain a phone number'
  );
}

if (!text) {
  throw new Error(
    `Inbound ${messageType} message does not contain usable text`
  );
}

/**
 * text:
 * texto enriquecido para procesamiento.
 *
 * storageText:
 * representación fiel de lo que realmente escribió
 * el cliente para guardarlo en messages.
 */
let storageText = text;

if (
  (
    messageType === 'IMAGE' ||
    messageType === 'DOCUMENT'
  ) &&
  hasOriginalText
) {
  storageText = originalText;
}

return {
  json: {
    phone,

    name,

    providerMessageId,

    messageType,

    text,

    storageText,

    originalText,

    media:
      input.media ?? null,

    transcription:
      input.transcription ?? null,

    imageAnalysis:
      input.imageAnalysis ?? null,

    documentAnalysis:
      input.documentAnalysis ?? null,

    whatsapp:
      input.whatsapp ?? null
  }
};

