      context.media,

    whatsapp:
      context.whatsapp
  },

  binary: {
    data:
      $binary.data
  }
};

const mediaContext =
  $('Restore Downloaded Media Context').item.json;

const transcript =
  typeof $json.text === 'string'
    ? $json.text.trim()
    : '';

if (!transcript) {
  throw new Error(
    'OpenAI returned an empty transcription for the WhatsApp audio'
  );
}

return {
  json: {
    phone:
      mediaContext.phone ?? null,

    name:
      mediaContext.name ?? null,

    providerMessageId:
      mediaContext.providerMessageId ?? null,

    messageType: 'AUDIO',

    text:
      transcript,

    media:
      mediaContext.media ?? null,

    transcription: {
      provider: 'OPENAI',

      usage:
        $json.usage ?? null
    },

    whatsapp:
      mediaContext.whatsapp ?? null
  }
};

const mediaContext =
  $('Restore Downloaded Media Context').item.json;

/**
 * Normaliza las diferentes estructuras que puede devolver
 * el nodo OpenAI de n8n y obtiene únicamente el texto.
 */
function extractText(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'string') {
    return value.trim();
  }

  if (Array.isArray(value)) {
    return value
      .map((item) => extractText(item))
      .filter(Boolean)
      .join('\n')
      .trim();
  }

  if (typeof value === 'object') {
    if (typeof value.text === 'string') {
      return value.text.trim();
    }

    if (typeof value.output_text === 'string') {
      return value.output_text.trim();
    }

    if (typeof value.description === 'string') {
      return value.description.trim();
    }

    if (value.content !== undefined) {
      const content = extractText(value.content);

      if (content) {
        return content;
      }
    }

    if (value.message !== undefined) {
      const message = extractText(value.message);

      if (message) {
        return message;
      }
    }

    if (value.response !== undefined) {
      const response = extractText(value.response);

      if (response) {
        return response;
      }
    }
  }

  return '';
}

const candidates = [
  $json.content,
  $json.text,
  $json.output_text,
  $json.description,
  $json.message,
  $json.response
];

let imageAnalysis = '';

for (const candidate of candidates) {
  imageAnalysis = extractText(candidate);

  if (imageAnalysis) {
    break;
  }
}

if (!imageAnalysis) {
  throw new Error(
    'OpenAI returned an empty analysis for the WhatsApp image'
  );
}

const originalCaption =
  typeof mediaContext.text === 'string'
    ? mediaContext.text.trim()
    : '';

let processingText = '';

if (originalCaption) {
  processingText = [
    'MENSAJE DEL CLIENTE:',
    originalCaption,
    '',
    'INFORMACION EXTRAIDA DE LA IMAGEN:',
    imageAnalysis
  ].join('\n');
} else {
  processingText = [
    'EL CLIENTE HA ENVIADO UNA IMAGEN.',
    '',
    'INFORMACION EXTRAIDA DE LA IMAGEN:',
    imageAnalysis
  ].join('\n');
}

return {
  json: {
    phone:
      mediaContext.phone ?? null,

    name:
      mediaContext.name ?? null,

    providerMessageId:
      mediaContext.providerMessageId ?? null,

    messageType: 'IMAGE',

    text:
      processingText,

    originalText:
      originalCaption || null,

    media:
      mediaContext.media ?? null,

    imageAnalysis: {
      provider: 'OPENAI',
      text: imageAnalysis
    },

    transcription: null,

    whatsapp:
      mediaContext.whatsapp ?? null
  }
};

const mediaContext =
  $('Restore Downloaded Media Context').item.json;

/**
 * Busca texto dentro de las diferentes estructuras
 * que puede devolver el nodo OpenAI.
 */
function extractText(value, depth = 0) {
  if (depth > 10) {
    return '';
  }

  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'string') {
    return value.trim();
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const result = extractText(item, depth + 1);

      if (result) {
        return result;
      }
    }

    return '';
  }

  if (typeof value === 'object') {
    const preferredKeys = [
      'output_text',
      'text',
      'content',
      'message',
      'response',
      'output',
      'result'
    ];

    for (const key of preferredKeys) {
      if (value[key] !== undefined) {
        const result =
          extractText(
            value[key],
            depth + 1
          );

        if (result) {
          return result;
        }
      }
    }

    for (const child of Object.values(value)) {
      const result =
        extractText(
          child,
          depth + 1
        );

      if (result) {
        return result;
      }
    }
  }

  return '';
}

const documentAnalysis =
  extractText($json);

if (!documentAnalysis) {
  throw new Error(
    'OpenAI returned an empty analysis for the WhatsApp PDF'
  );
}

const originalCaption =
  typeof mediaContext.text === 'string'
    ? mediaContext.text.trim()
    : '';

const filename =
  mediaContext.media?.filename ?? null;

const parts = [];

if (originalCaption) {
  parts.push(
    'MENSAJE DEL CLIENTE:',
    originalCaption,
    ''
  );
}

parts.push(
  'DOCUMENTO ENVIADO POR EL CLIENTE:'
);

if (filename) {
  parts.push(
    `ARCHIVO: ${filename}`
  );
}

parts.push(
  '',
  'INFORMACION EXTRAIDA DEL DOCUMENTO:',
  documentAnalysis
);

const processingText =
  parts.join('\n');

return {
  json: {
    phone:
      mediaContext.phone ?? null,

    name:
      mediaContext.name ?? null,

    providerMessageId:
      mediaContext.providerMessageId ?? null,

    messageType: 'DOCUMENT',

    /**
     * Esto es lo que utilizará la IA del flujo
     * para entender la petición.
     */
    text:
      processingText,

    /**
     * Caption realmente escrito por el cliente.
     */
    originalText:
      originalCaption || null,

    media:
      mediaContext.media ?? null,

    documentAnalysis: {
      provider: 'OPENAI',
      type: 'PDF',
      text: documentAnalysis
    },

    transcription: null,

    imageAnalysis: null,

    whatsapp:
      mediaContext.whatsapp ?? null
  }
};

const originalCaption =
  typeof $json.text === 'string'
    ? $json.text.trim()
    : '';

const filename =
  $json.media?.filename ?? null;

const mimeType =
  $json.media?.mimeType ?? null;

const parts = [
  'EL CLIENTE HA ENVIADO UN DOCUMENTO.'
];

if (originalCaption) {
  parts.push(
    '',
    'MENSAJE DEL CLIENTE:',
    originalCaption
  );
}

if (filename) {
  parts.push(
    '',
    `ARCHIVO: ${filename}`
  );
}

if (mimeType) {
  parts.push(
    `TIPO DE ARCHIVO: ${mimeType}`
  );
}

parts.push(
  '',
  'EL CONTENIDO DEL DOCUMENTO NO HA SIDO ANALIZADO AUTOMATICAMENTE.'
);

return {
  json: {
    phone:
      $json.phone ?? null,

    name:
      $json.name ?? null,

    providerMessageId:
      $json.providerMessageId ?? null,

    messageType: 'DOCUMENT',

    text:
      parts.join('\n'),

    originalText:
      originalCaption || null,

    media:
      $json.media ?? null,

    documentAnalysis: {
      provider: null,
      type: 'UNSUPPORTED',
      text: null
    },

    transcription: null,

    imageAnalysis: null,

    whatsapp:
      $json.whatsapp ?? null
  }
};

const input = $json;

const MB = 1024 * 1024;

const policy = {
  AUDIO: {
    maxBytes: 20 * MB,
    maxMB: 20,

    allowedMimeTypes: [
      'audio/ogg',
      'audio/opus',
      'audio/mpeg',
      'audio/mp4',
      'audio/aac',
      'audio/amr'
    ]
  },

  IMAGE: {
    maxBytes: 10 * MB,
    maxMB: 10,

    allowedMimeTypes: [
      'image/jpeg',
      'image/png',
      'image/webp'
    ]
  },

  DOCUMENT: {
    maxBytes: 15 * MB,
    maxMB: 15,

    allowedMimeTypes: [
      'application/pdf'
    ]
  }
};

const messageType =
  input.messageType ?? null;

const mediaPolicy =
  policy[messageType];

const rawMimeType =
  input.media?.mimeType ?? '';

const normalizedMimeType =
  rawMimeType
    .split(';')[0]
    .trim()
    .toLowerCase();

const fileSize =
  Number(input.media?.fileSize);

let accepted = true;
let reasonCode = null;
let reason = null;

if (!mediaPolicy) {
  accepted = false;

  reasonCode =
    'UNSUPPORTED_MEDIA_TYPE';

  reason =
    `Unsupported media type: ${messageType}`;
}

if (
  accepted &&
  (
    !Number.isFinite(fileSize) ||
    fileSize <= 0
  )
) {
  accepted = false;

  reasonCode =
    'FILE_SIZE_UNKNOWN';

  reason =
    'Media file size could not be verified';
}

if (
  accepted &&
  !mediaPolicy.allowedMimeTypes.includes(
    normalizedMimeType
  )
) {
  accepted = false;

  reasonCode =
    'UNSUPPORTED_MIME_TYPE';

  reason =
    `Unsupported MIME type: ${normalizedMimeType}`;
}

if (
  accepted &&
  fileSize > mediaPolicy.maxBytes
) {
  accepted = false;

  reasonCode =
    'FILE_TOO_LARGE';

  reason =
    `File exceeds ${mediaPolicy.maxMB} MB limit`;
}

return {
  json: {
    ...input,

    media: {
      ...input.media,

      originalMimeType:
        rawMimeType || null,

      mimeType:
        normalizedMimeType || null
    },

    mediaValidation: {
      accepted,

      reasonCode,

      reason,

      fileSizeBytes:
        Number.isFinite(fileSize)
          ? fileSize
          : null,

      fileSizeMB:
        Number.isFinite(fileSize)
          ? Number(
              (
                fileSize / MB
              ).toFixed(2)
            )
          : null,

      maxSizeMB:
        mediaPolicy?.maxMB ?? null,

      mimeType:
        normalizedMimeType || null
    }
  }
};

const validation =
  $json.mediaValidation ?? {};

const type =
  $json.messageType ?? 'OTHER';

const reasonCode =
  validation.reasonCode ?? 'UNKNOWN';

let text =
  'No he podido procesar el archivo. Intenta enviarlo de nuevo.';

if (
  reasonCode ===
  'FILE_TOO_LARGE'
) {
  text =
    `El archivo es demasiado grande. ` +
    `Para este tipo de archivo el máximo es de ` +
    `${validation.maxSizeMB} MB.`;
}

else if (
  reasonCode ===
  'FILE_SIZE_UNKNOWN'
) {
  text =
    'No he podido comprobar correctamente el tamaño del archivo. ' +
    'Prueba a enviarlo de nuevo.';
}

else if (
  reasonCode ===
  'UNSUPPORTED_MIME_TYPE'
) {
  if (type === 'AUDIO') {
    text =
      'No puedo procesar ese formato de audio. ' +
      'Envíamelo como una nota de voz normal de WhatsApp.';
  }

  else if (type === 'IMAGE') {
    text =
      'No puedo procesar ese formato de imagen. ' +
      'Envíamela como JPG, PNG o WEBP.';
  }

  else if (type === 'DOCUMENT') {
    text =
      'Por ahora puedo analizar documentos en formato PDF. ' +
      'Envíamelo como PDF y podré revisarlo.';
  }
}

else if (
  reasonCode ===
  'UNSUPPORTED_MEDIA_TYPE'
) {
  text =
    'Ese tipo de archivo todavía no puedo procesarlo. ' +
    'Puedes enviarme texto, una nota de voz, una imagen o un PDF.';
}

return {
  json: {
    phone:
      $json.phone ?? null,

    phoneNumberId:
      $json.whatsapp?.phoneNumberId ?? null,

    text,

    purpose:
      'MEDIA_REJECTED',

    generatedBy:
      'SYSTEM',

    rejectedMedia: {
      messageType:
        type,

      mediaId:
        $json.media?.id ?? null,

      mimeType:
        $json.media?.mimeType ?? null,

      fileSizeBytes:
        validation.fileSizeBytes ?? null,

      reasonCode:
        validation.reasonCode ?? null,

      reason:
        validation.reason ?? null
    }
  }
};

const original =
  $('Normalize WhatsApp Inbound').item.json;

if (!original.providerMessageId) {
  throw new Error(
    'Inbound WhatsApp message does not contain a providerMessageId'
  );
}

return {
  json: {
    ...original
  }
};
